                    build.skir.Serializers.list(
                        skirout.editor.v1.diagnostic.TypeDiagnostic.serializer,
                    ),
                    "",
                    { DiagnosticsWrapper(it) },
                    { it.value },
                );
                _serializerImpl.finalizeEnum();
            }
        }
    }
